#!/usr/bin/env python3
# Instala Constelacao Eterea e resultado automatico apos cinco segundos.
# Execute na raiz do repositorio: python instalar_constelacao_eterea.py
from pathlib import Path
import sys

ROOT = Path.cwd()
DIR = ROOT / "labour-law"
BANKS = (
    "convencao-acordo-coletivo",
    "contribuicao-sindical",
    "contribuicao-confederativa",
    "mensalidade-sindical",
    "contribuicao-assistencial",
    "liberdade-sindical",
    "organizacao-sindical",
    "aviso-previo",
    "suspensao-interrupcao-contrato",
)
CSS = "/* Legis Lectiones — Constelacao Eterea. Apenas resultados com nota > 70%. */\n#result.ll-celestial {\n  isolation: isolate;\n  position: relative;\n  overflow: hidden;\n  border: 1px solid rgba(118, 165, 227, .41);\n  border-radius: 23px;\n  background:\n    radial-gradient(ellipse at 50% 38%, rgba(37, 83, 132, .39), transparent 62%),\n    linear-gradient(150deg, #10213a, #0a1629 60%, #07111e);\n  box-shadow:\n    0 0 0 1px rgba(171, 203, 246, .05),\n    0 20px 68px rgba(3, 9, 24, .45),\n    inset 0 0 50px rgba(67, 102, 165, .10);\n}\n/* Remove o adorno antigo apenas quando a constelacao esta ativa. */\n#result.ll-celestial::before { content: none; display: none; }\n#result.ll-celestial > :not(.ll-stellar-scene) {\n  position: relative;\n  z-index: 2;\n}\n#result.ll-celestial .eyebrow { color: #9fc2ee; }\n#result.ll-celestial h2 { color: #f3f7ff; }\n#result.ll-celestial #score {\n  position: relative;\n  color: #f0f8ff;\n  background: none;\n  -webkit-text-fill-color: #f0f8ff;\n  font-family: 'DM Sans', sans-serif;\n  font-size: clamp(76px, 14vw, 112px);\n  font-weight: 650;\n  letter-spacing: -.075em;\n  line-height: 1.08;\n  margin: 22px 0 20px;\n  text-shadow: 0 0 16px rgba(157, 210, 255, .58),\n               0 0 62px rgba(73, 139, 221, .50);\n  animation: ll-score-appear 1100ms ease-out both,\n             ll-score-glow 4.8s ease-in-out 1100ms infinite alternate;\n}\n#result.ll-celestial #scoreDetail { color: #b7c8df; }\n#result.ll-celestial .result-actions { margin-top: 28px; }\n\n/* Decoracao totalmente passiva: nao interfere com botoes nem selecao. */\n#result .ll-stellar-scene { display: none; }\n#result.ll-celestial .ll-stellar-scene {\n  display: block;\n  position: absolute;\n  z-index: 0;\n  inset: 0;\n  overflow: hidden;\n  border-radius: inherit;\n  pointer-events: none;\n}\n#result.ll-celestial .ll-stellar-scene::before {\n  content: '';\n  position: absolute;\n  inset: -42%;\n  background: repeating-conic-gradient(from 20deg at 50% 45%,\n    transparent 0deg 22deg,\n    rgba(140, 194, 255, .07) 22.3deg 22.8deg,\n    transparent 23deg 39deg);\n  opacity: .70;\n  animation: ll-celestial-turn 48s linear infinite;\n}\n#result.ll-celestial .ll-stellar-scene::after {\n  content: '';\n  position: absolute;\n  inset: 0;\n  background: radial-gradient(ellipse at 50% 38%,\n     rgba(91, 153, 224, .13), transparent 54%);\n  animation: ll-celestial-breathe 5s ease-in-out infinite alternate;\n}\n#result.ll-celestial .ll-stellar-star {\n  position: absolute;\n  z-index: 1;\n  left: var(--ll-x);\n  top: var(--ll-y);\n  width: var(--ll-size);\n  height: var(--ll-size);\n  border-radius: 50%;\n  background: #e8f5ff;\n  box-shadow: 0 0 7px rgba(192, 227, 255, .86),\n              0 0 16px rgba(119, 176, 255, .46);\n  opacity: .75;\n  animation: ll-celestial-twinkle var(--ll-duration) ease-in-out var(--ll-delay) infinite alternate;\n}\n#result.ll-celestial .ll-stellar-orbit {\n  position: absolute;\n  left: 50%;\n  top: 41%;\n  width: min(68%, 475px);\n  height: clamp(105px, 15vw, 164px);\n  border: 1px solid rgba(130, 174, 232, .24);\n  border-radius: 50%;\n  box-shadow: inset 0 0 16px rgba(105, 161, 238, .065),\n              0 0 24px rgba(98, 142, 218, .08);\n  transform: translate(-50%, -50%) rotate(-16deg);\n  animation: ll-celestial-orbit 11s ease-in-out infinite alternate;\n}\n#result.ll-celestial .ll-stellar-orbit--outer {\n  width: min(80%, 560px);\n  height: clamp(132px, 20vw, 211px);\n  border-color: rgba(162, 177, 239, .16);\n  transform: translate(-50%, -50%) rotate(22deg);\n  animation-duration: 14s;\n  animation-direction: alternate-reverse;\n}\n#result.ll-celestial .ll-stellar-orbit::before {\n  content: '✦';\n  position: absolute;\n  top: -14px;\n  left: 13%;\n  font-size: 18px;\n  color: #dbf3ff;\n  text-shadow: 0 0 11px #b7e2ff, 0 0 21px #82aaf8;\n}\n#result.ll-celestial .ll-stellar-orbit--outer::before {\n  top: auto;\n  bottom: -11px;\n  left: 78%;\n  font-size: 12px;\n  color: #baabff;\n}\n@keyframes ll-celestial-turn { to { transform: rotate(360deg); } }\n@keyframes ll-celestial-breathe { to { opacity: .35; transform: scale(.97); } }\n@keyframes ll-celestial-twinkle {\n  from { opacity: .14; transform: scale(.67) translateY(0); }\n  to { opacity: .90; transform: scale(1.25) translateY(-3px); }\n}\n@keyframes ll-celestial-orbit {\n  from { opacity: .56; transform: translate(-50%, -50%) rotate(-16deg) scale(.99); }\n  to { opacity: .95; transform: translate(-50%, -50%) rotate(-8deg) scale(1.02); }\n}\n@keyframes ll-score-appear {\n  from { opacity: .42; transform: translateY(12px) scale(.94); filter: blur(3px); }\n  to { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }\n}\n@keyframes ll-score-glow {\n  to { text-shadow: 0 0 24px rgba(179, 226, 255, .89),\n                    0 0 82px rgba(94, 147, 224, .65); }\n}\n#result.ll-celestial .ll-stellar-orbit--outer {\n  animation-name: ll-celestial-outer;\n}\n@keyframes ll-celestial-outer {\n  from { opacity: .44; transform: translate(-50%, -50%) rotate(22deg) scale(.99); }\n  to { opacity: .83; transform: translate(-50%, -50%) rotate(13deg) scale(1.01); }\n}\n@media (max-width: 600px) {\n  #result.ll-celestial .ll-stellar-orbit { width: 84%; height: 120px; }\n  #result.ll-celestial .ll-stellar-orbit--outer { width: 96%; height: 156px; }\n  #result.ll-celestial #score { font-size: clamp(68px, 17vw, 89px); }\n}\n@media (prefers-reduced-motion: reduce) {\n  #result.ll-celestial #score,\n  #result.ll-celestial .ll-stellar-star,\n  #result.ll-celestial .ll-stellar-orbit,\n  #result.ll-celestial .ll-stellar-scene::before,\n  #result.ll-celestial .ll-stellar-scene::after {\n    animation: none !important;\n  }\n}\n"
JS = '/* Legis Lectiones — resultado automatico e celebracao Constelacao Eterea.\n   Compatibilidade: 5 bancos antigos + 4 bancos P2.\n   Nao altera gabaritos, status, som de respostas nem os eventos do engagement. */\n(() => {\n  \'use strict\';\n\n  const byId = id => document.getElementById(id);\n  const result = byId(\'result\');\n  const finish = byId(\'finishBtn\');\n  const progressBar = byId(\'progressBar\');\n  const scoreDetail = byId(\'scoreDetail\');\n  if (!result || !finish || !progressBar || !scoreDetail) return;\n\n  const SOUND_URL = new URL(\'../civil-procedure/win.mp3\', document.baseURI).href;\n  const AUTO_DELAY_MS = 5000;\n  let lastComplete = null;\n  let autoTimer = null;\n  let celebratedThisAttempt = false;\n  let webAudio = null;\n  let decodedWin = null;\n  let winBufferRequested = false;\n  let winAudioElement = null;\n\n  const showingResult = () => result.classList.contains(\'show\');\n\n  function exactScore() {\n    // Usa quantidades reais, nao o percentual exibido (que e arredondado).\n    const text = scoreDetail.textContent || \'\';\n    const hits = text.match(/\\b(\\d+)\\s+acertos?\\b/i);\n    const total = text.match(/\\b(\\d+)\\s+atividades?\\b/i);\n    if (!hits || !total) return null;\n    const right = Number(hits[1]);\n    const count = Number(total[1]);\n    return count > 0 && right >= 0 && right <= count ? right / count : null;\n  }\n\n  function createScene() {\n    if (result.querySelector(\'.ll-stellar-scene\')) return;\n    const scene = document.createElement(\'div\');\n    scene.className = \'ll-stellar-scene\';\n    scene.setAttribute(\'aria-hidden\', \'true\');\n    for (const kind of [\'inner\', \'outer\']) {\n      const orbit = document.createElement(\'span\');\n      orbit.className = \'ll-stellar-orbit\' + (kind === \'outer\' ? \' ll-stellar-orbit--outer\' : \'\');\n      scene.appendChild(orbit);\n    }\n    for (let i = 0; i < 34; i++) {\n      // Distribuicao deterministica, para evitar movimento aleatorio ou saltos ao reabrir.\n      const star = document.createElement(\'span\');\n      star.className = \'ll-stellar-star\';\n      star.style.setProperty(\'--ll-x\', `${(11 + i * 37) % 94}%`);\n      star.style.setProperty(\'--ll-y\', `${(7 + i * 29) % 90}%`);\n      star.style.setProperty(\'--ll-size\', `${i % 7 === 0 ? 3 : i % 3 === 0 ? 2 : 1}px`);\n      star.style.setProperty(\'--ll-duration\', `${2.4 + (i % 6) * 0.43}s`);\n      star.style.setProperty(\'--ll-delay\', `${(i % 8) * -0.49}s`);\n      scene.appendChild(star);\n    }\n    result.prepend(scene);\n  }\n\n  function applyResultTheme() {\n    if (!showingResult()) return;\n    const ratio = exactScore();\n    const shouldCelebrate = ratio !== null && ratio > 0.70;\n    // Evita mostrar "70%" em uma conquista de 70,1% arredondada.\n    const score = byId(\'score\');\n    if (shouldCelebrate && score && /^70%$/.test(score.textContent.trim())) {\n      score.textContent = (ratio * 100).toFixed(1).replace(\'.\', \',\') + \'%\';\n    }\n    if (shouldCelebrate) createScene();\n    result.classList.toggle(\'ll-celestial\', shouldCelebrate);\n  }\n\n  function armAudio() {\n    const Ctx = window.AudioContext || window.webkitAudioContext;\n    if (!Ctx) return;\n    try {\n      if (!webAudio) webAudio = new Ctx();\n      if (webAudio.state === \'suspended\') {\n        Promise.resolve(webAudio.resume()).catch(() => {});\n      }\n      if (!winBufferRequested) {\n        winBufferRequested = true;\n        fetch(SOUND_URL)\n          .then(response => {\n            if (!response.ok) throw new Error(`HTTP ${response.status}`);\n            return response.arrayBuffer();\n          })\n          .then(buffer => webAudio.decodeAudioData(buffer))\n          .then(buffer => { decodedWin = buffer; })\n          .catch(() => {}); // Um elemento <audio> permanece como alternativa.\n      }\n    } catch (_) { /* AudioContext pode ser indisponivel no dispositivo. */ }\n  }\n\n  function playWinOnce() {\n    if (celebratedThisAttempt || !showingResult() || exactScore() === null || exactScore() <= 0.70) return;\n    celebratedThisAttempt = true;\n\n    // WebAudio desbloqueado por interacao anterior permite tocar apos o delay.\n    if (webAudio && decodedWin && webAudio.state === \'running\') {\n      try {\n        const source = webAudio.createBufferSource();\n        source.buffer = decodedWin;\n        source.connect(webAudio.destination);\n        source.start(0);\n        return;\n      } catch (_) { /* Recorrer ao HTMLAudio abaixo. */ }\n    }\n    try {\n      if (!winAudioElement) {\n        winAudioElement = new Audio(SOUND_URL);\n        winAudioElement.preload = \'auto\';\n      }\n      winAudioElement.currentTime = 0;\n      const promise = winAudioElement.play();\n      if (promise && typeof promise.catch === \'function\') promise.catch(() => {});\n    } catch (_) { /* Nao interromper o resultado quando o browser bloqueia som. */ }\n  }\n\n  // Desbloqueio facultativo de som durante um gesto real do estudante.\n  document.addEventListener(\'pointerdown\', armAudio, { once: true, capture: true });\n  document.addEventListener(\'keydown\', armAudio, { once: true, capture: true });\n\n  function stopAuto() {\n    if (autoTimer !== null) {\n      clearTimeout(autoTimer);\n      autoTimer = null;\n    }\n  }\n\n  function isFullyAnswered() {\n    const raw = progressBar.style.width;\n    if (!raw || !raw.trim().endsWith(\'%\')) return false;\n    const width = Number.parseFloat(raw);\n    return Number.isFinite(width) && width >= 99.9999 && width <= 100.0001;\n  }\n\n  function scheduleAuto() {\n    stopAuto();\n    if (showingResult()) return;\n    autoTimer = setTimeout(() => {\n      autoTimer = null;\n      if (!isFullyAnswered() || showingResult()) return;\n      // Chama o proprio botao: preserva calculo, D1, evento law-bank-result e UI.\n      finish.click();\n    }, AUTO_DELAY_MS);\n  }\n\n  function watchProgress() {\n    // Aguarde o primeiro valor real: evita agendar ao abrir um banco ja completo.\n    if (!progressBar.style.width || !progressBar.style.width.trim().endsWith(\'%\')) return;\n    const completed = isFullyAnswered();\n    if (lastComplete === null) {\n      // Nao redirecionar quem apenas recarregou um banco ja concluido.\n      lastComplete = completed;\n      return;\n    }\n    if (!completed) stopAuto();\n    if (completed && !lastComplete) scheduleAuto();\n    lastComplete = completed;\n  }\n\n  const observer = new MutationObserver(watchProgress);\n  observer.observe(progressBar, {attributes:true, attributeFilter:[\'style\']});\n  watchProgress();\n\n  // O motor emite esse evento depois de construir o resultado e seu placar.\n  window.addEventListener(\'law-bank-result\', applyResultTheme);\n\n  // O bubble listener roda DEPOIS do handler nativo do botao Resultado,\n  // ainda no gesto do usuario (importante para reproduzir win.mp3 no Safari).\n  document.addEventListener(\'click\', event => {\n    const clicked = event.target;\n    if (!(clicked instanceof Element)) return;\n    if (clicked.closest(\'#finishBtn\') === finish) {\n      stopAuto();\n      applyResultTheme();\n      playWinOnce();\n    } else if (clicked.closest(\'#restartBtn\')) {\n      stopAuto();\n      celebratedThisAttempt = false;\n      result.classList.remove(\'ll-celestial\');\n    } else if (clicked.closest(\'#reviewWrongBtn\')) {\n      stopAuto();\n      result.classList.remove(\'ll-celestial\');\n    }\n  });\n})();\n'
CSS_LINE = '<link rel="stylesheet" href="./result-celestial.css">'
JS_LINE = '<script src="./result-celestial.js" defer></script>'


def main():
    if not DIR.is_dir():
        raise SystemExit("ERRO: execute na raiz do repositorio, onde existe labour-law/.")
    edits = []
    for name in BANKS:
        path = DIR / (name + ".html")
        if not path.is_file():
            raise SystemExit(f"ERRO: falta {path}. Nenhum arquivo alterado.")
        old = path.read_text(encoding="utf-8")
        required = ('</head>', 'id="result"', 'id="score"',
                    'id="scoreDetail"', 'id="progressBar"', 'id="finishBtn"')
        if any(old.count(marker) != 1 for marker in required):
            raise SystemExit(f"ERRO: estrutura inesperada em {path}. Nenhum arquivo alterado.")
        new = old
        links = []
        if CSS_LINE not in new:
            links.append('  ' + CSS_LINE)
        if JS_LINE not in new:
            links.append('  ' + JS_LINE)
        if links:
            new = new.replace('</head>', '\n'.join(links) + '\n</head>', 1)
        edits.append((path, old, new))
    # Nao sobrescreve assets existentes e diferentes sem intervencao consciente.
    for filename, content in (('result-celestial.css', CSS), ('result-celestial.js', JS)):
        dest = DIR / filename
        if dest.exists() and dest.read_text(encoding="utf-8") != content:
            raise SystemExit(f"ERRO: {dest} ja existe com conteudo diferente. Nenhum arquivo alterado.")
    for filename, content in (('result-celestial.css', CSS), ('result-celestial.js', JS)):
        dest = DIR / filename
        if not dest.exists():
            dest.write_text(content, encoding="utf-8")
            print(f"+ Criado: {dest.relative_to(ROOT)}")
        else:
            print(f"= Ja atualizado: {dest.relative_to(ROOT)}")
    for path, old, new in edits:
        if new != old:
            path.write_text(new, encoding="utf-8")
            print(f"+ Vinculado: {path.relative_to(ROOT)}")
        else:
            print(f"= Ja vinculado: {path.relative_to(ROOT)}")
    print("\nConstelacao Eterea instalada nos nove bancos.")
    print("Nao foram alterados arquivos JSON, motores de quiz nem engagement.")


if __name__ == "__main__":
    main()
